CREATE   VIEW [CE].[vwRicsAPC]
AS 
SELECT 
	apc.[rics_apcid],
	apc.[Rics_Name],
	apc.[created_on],
	apc.[CreatedBy],
	apc.[CreatedByName],
	apc.[Modified_On],
	apc.[ModifiedBy],
	apc.[ModifiedByName],
	apc.[rics_applicationenddate],
	apc.[rics_applicationtypeid],
	apc.[rics_applicationtypeidname],
	apc.[rics_contactno],
	apc.[rics_contactid],
	apc.[rics_contactidname],
	apc.[rics_contactidYomiName],
	apc.[rics_electiondate],
	apc.[Rics_ExpectedFinalDate],
	apc.[rics_enrolmentdate],
	apc.[rics_enrolmentfee_base],
	apc.[rics_enrolmentfee],
	apc.[Rics_NumberofAttempts],
	apc.[rics_enrolmentlocalgroupid],
	apc.[Rics_EnrolmentLocalGroupIdName],
	apc.[rics_pathwayid],
	apc.[rics_pathwayidname],
	apc.[rics_routeid],
	apc.[rics_routeidname],

	apc.[rics_assessmentdeclarationaccepted],
	apc.[rics_finalassessmentformreceived],
	apc.[rics_submissionreceived],	
	apc.[rics_outcome],
	apc.[rics_outcome_Description],

	apc.[statecode],
	apc.[StateCode_Description],
	apc.[statuscode],
	apc.[StatusCode_Description],
	--apc.[rics_counsellorid],
	cr.[apuk_counsellorid] AS [rics_counsellorid],
	--apc.[rics_counselloridName],
	cnt.[FullName] AS [rics_counselloridName],
	apc.[Rics_ApplicationRecieved],
	apc.[rics_relevantacademicqualification],
	apc.[rics_relevantprofessionalbody],
	apc.[rics_relevantprofessionalexperience],
	apc.[ricsv1_spaspecialiststatement],
	apc.[rics_areaofqualification],
	apc.[rics_vocationalqualification],
	apc.[rics_confirmationemaildate],
	apc.[ricsv1_statementsubmitted],
	apc.[ricsv1_vettingcompletedcontinueapplication],
	apc.[ricsv1_vettingcompletedcontinueapplication_Description],
	apc.[ricsv1_oedeclarationaccepted],
	apc.[ricsv1_oedeclarationaccepted_Description],
	apc.[ricsv1_oedeclarationsubmitted],
	apc.[ricsv1_oedeclarationsubmitted_Description],
	apc.[ricsv1_oedateofsubmission],
	apc.[rics_ethicstestcompletiondate],
	apc.[rics_finalassessmentformrecieved],
	apc.[ricsv1_arcdeclarationaccepted],
	apc.[ricsv1_arcdeclarationaccepted_Description],
	apc.[ricsv1_arcdeclarationsubmitted],
	apc.[ricsv1_arcdeclarationsubmitted_Description],
	apc.[rics_refereeoneid],
	apc.[rics_refereetwoid],
	apc.[ricsv1_seconder2],
	apc.[ricsv1_proposerapproved],
	apc.[ricsv1_proposerapproved_Description],
	apc.[ricsv1_proposerapproveddate],
	apc.[ricsv1_seconder1approved],
	apc.[ricsv1_seconder1approved_Description],
	apc.[ricsv1_seconder1approveddate],
	apc.[ricsv1_seconder2approved],
	apc.[ricsv1_seconder2approved_Description],
	apc.[ricsv1_seconder2approveddate],
	apc.[apuk_ricsrecordid],
	apc.[apuk_arclastloggedin],
	apc.[apuk_preliminarysubmissionreceived],
	apc.[apuk_extensionuntil],
	apc.[apuk_previouslyreferred],
	apc.[apuk_industrysectorid]
	,r.[ricsv2_enrolmenttypeId]
	,r.[ricsv2_EnrolmentTypeIdName]
FROM [synapse_ce].[vwRicsApc] apc
	LEFT JOIN [synapse_ce].[vwCounsellorRelationship] cr
		ON apc.[rics_counsellorid] = cr.[apuk_counsellorrelationshipid]
	LEFT JOIN [synapse_ce].[tblContact_BI] cnt
		ON cr.[apuk_counsellorid] = cnt.[ContactId]
	LEFT JOIN [CE].[vwRics_Route] AS r 
		ON apc.rics_routeid = r.rics_routeid
		AND apc.rics_applicationtypeid = r.rics_applicationtypeid
